// Déclarations ambiantes. Ce fichier ne doit contenir ni `import` ni `export` :
// il deviendrait un module et ses déclarations ne seraient plus globales.

// TypeScript 6 vérifie les imports à effet de bord : le paquet de la police
// n'expose que du CSS, sans déclaration de types.
declare module '@fontsource-variable/dm-sans';
